mapper.select:
SELECT COUNT(*)
FROM crm_customer
WHERE deleted = 0
  AND heat_score >= 80

  AND advisor_id = #{advisorId}


  AND manager_id = #{managerId}

SELECT COUNT(*)
FROM crm_customer
WHERE deleted = 0
  AND DATE(created_at) = CURDATE()

  AND advisor_id = #{advisorId}


  AND manager_id = #{managerId}

SELECT COUNT(*)
FROM crm_customer
WHERE deleted = 0

  AND advisor_id = #{advisorId}


  AND manager_id = #{managerId}


  AND status = #{status}

SELECT COUNT(*) FROM crm_task t LEFT JOIN crm_customer c ON t.customer_id = c.id WHERE t.deleted = 0 AND t.status = 'PENDING'
AND t.owner_id = #{ownerId}
AND c.manager_id = #{managerId}

SELECT t.id, t.customer_id, c.customer_name, t.title, t.status, t.priority, t.task_date, t.task_time FROM crm_task t LEFT JOIN crm_customer c ON t.customer_id = c.id WHERE t.deleted = 0 AND t.task_date = CURDATE()
AND t.owner_id = #{ownerId}
ORDER BY t.task_time ASC, t.created_at DESC LIMIT #{limit}

SELECT c.id, c.customer_name, c.mobile, c.status, c.intent_level, c.heat_score, u.nickname AS advisor_name FROM crm_customer c LEFT JOIN sys_user u ON c.advisor_id = u.id WHERE c.deleted = 0 AND c.heat_score >= 80
AND c.advisor_id = #{advisorId}
AND c.manager_id = #{managerId}
ORDER BY c.heat_score DESC, c.updated_at DESC LIMIT #{limit}
